#define TAO_DEVICE_ZERO_GRAD
#include "batch_tape.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{for(unsigned n:{129u,512u}){unsigned S=4;Vec x(n*S),g(n),dy(n*S);for(size_t i=0;i<x.size();++i){x[i]=float(int(i%23)-11)*.03f;dy[i]=float(int(i%17)-8)*.07f;}for(unsigned i=0;i<n;++i)g[i]=.8f+float(i%3)*.1f;BatchTape t;auto X=t.leaf(x),G=t.leaf(g),Y=t.norm_batch(X,G,S);check(cudaMemcpy(Y->grad.p,dy.data(),dy.size()*4,cudaMemcpyHostToDevice));t.backward();Device ref(n*S),dx(Vec(n*S,0)),dg(Vec(n,0)),D(dy);for(unsigned s=0;s<S;++s){rms_parallel<<<1,256>>>(X->value.p+s*n,G->value.p,ref.p+s*n,n);rms_back_parallel<<<1,256>>>(X->value.p+s*n,G->value.p,D.p+s*n,dx.p+s*n,dg.p,n);}check(cudaGetLastError());float maxerr=0;auto cmp=[&](Vec a,Vec b){for(size_t i=0;i<a.size();++i){if(!std::isfinite(b[i]))throw std::runtime_error("nonfinite");maxerr=std::max(maxerr,std::abs(a[i]-b[i]));}};cmp(ref.host(),Y->value.host());cmp(dx.host(),X->grad.host());cmp(dg.host(),G->grad.host());printf("n=%u maxabs=%.9g\n",n,maxerr);if(maxerr>1e-5)return 1;}printf("PASS batch RMS values dx shared gamma gradients within1e-5 vs serial4; not bitwise\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 2;}}
